mapper.sql:
WHERE f.use_yn = 'Y'

    AND f.category_code = #{categoryCode}



    AND (f.question LIKE #{searchPattern} OR f.answer LIKE #{searchPattern})

mapper.select:
SELECT f.faq_id, f.category_code, c.code_name AS category_name, f.question, f.answer, f.sort_order, f.created_at, f.updated_at FROM faq f LEFT JOIN com_code_detail c ON c.group_id = 'FAQ_CATEGORY' AND c.code_id = f.category_code
ORDER BY c.sort_order, f.sort_order, f.faq_id
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO faq (
    faq_id, category_code, question, answer, sort_order, use_yn, writer_id, created_at
) VALUES (
    #{faqId}, #{categoryCode}, #{question}, #{answer}, #{sortOrder}, 'Y', #{audit.userId}, #{audit.now}
)

mapper.update:
UPDATE faq
SET use_yn = 'N',
    updated_by = #{audit.userId},
    updated_at = #{audit.now}
WHERE faq_id = #{faqId}
  AND use_yn = 'Y'
